L41_1 = "부디 자네들이 구한 아이들이 이곳에서 최대한 멀리 떨어졌길 바라지."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "君たちが助けた子どもたちが、ここから遠く離れていることを祈るよ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I hope that the children you saved are far away from here as possible."
