L45_1 = "마지막에 떠오르는 것은 폭발에서 우리를 지키려던 요원님의 품과."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "最後に思い出すのは、爆発から私たちを守ろうとするエージェント様の懐と。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "The last thing I recall is the agent's arms protecting us from the explosion, and..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "最後出現的，是在爆炸中守護我們的大人的懷抱……"
L44_1.m_Talk_TWN = L45_1
