L44_1.m_Talk_SCN = L45_1
L45_1 = "The last thing I recall is the agent's arms protecting us from the explosion, and..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "The last thing I recall is the agent's arms protecting us from the explosion, and..."
L44_1.m_Talk_FRA = L45_1
