L28_1 = "PRYDWEN_ACT3_INTERUDE4@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 6000306
L27_1.m_CutScenStrID = "PRYDWEN_ACT3_INTERUDE4"
