L28_1 = "ANNA_PRYDWEN_NPC_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "로젠탈에서 주입하고 있는 파편에는 사실, 내 사념이 깃들어 있었거든."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "実はローゼンタールで注入していた破片には私の思念が宿っていたの。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "The Fragments they injected the children with at Rosenthal actually contained my consciousness."
L27_1.m_Talk_ENG = L28_1
L28_1 = "在羅森泰注入的碎片中，其實寄宿著我的意念。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "在罗森塔尔注入的碎片中，其实寄宿着我的念灵。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "The Fragments they injected the children with at Rosenthal actually contained my consciousness."
L27_1.m_Talk_DEU = L28_1
L28_1 = "The Fragments they injected the children with at Rosenthal actually contained my consciousness."
L27_1.m_Talk_FRA = L28_1
