L29_1 = "PRYDWEN_ACT3_INTERUDE4@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 6000306
L28_1.m_CutScenStrID = "PRYDWEN_ACT3_INTERUDE4"
L28_1.m_bWaitClick = true
