L28_1.m_Face = "UNIT_HATE"
L29_1 = "ANNA_PRYDWEN_NPC_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "에델, 그 망할 년 때문에 이 몸에 깃든 것이 내 <color=#ffd34c>마지막 사념</color>이 될 줄 몰랐지만 말이야."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "エデル、あのクソ女のせいでこの肉体に宿したのが私の<color=#ffd34c>最後の思念</color>になるとは思わなかったけどね。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "But because of that bitch Edel, I never imagined that the consciousness to pervade this body would be <color=#ffd34c>my last</color>."
L28_1.m_Talk_ENG = L29_1
L29_1 = "只是沒想到會因為艾瑟兒那個臭女人，這副身軀蘊含的會是我<color=#ffd34c>最後的意念</color>。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "只是没想到会因为埃德尔那个贱人，这副身躯蕴含的会是我<color=#ffd34c>最后的念灵</color>。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "But because of that bitch Edel, I never imagined that the consciousness to pervade this body would be <color=#ffd34c>my last</color>."
L28_1.m_Talk_DEU = L29_1
L29_1 = "But because of that bitch Edel, I never imagined that the consciousness to pervade this body would be <color=#ffd34c>my last</color>."
