L34_1 = "뭐, 이 아이의 인격과 내 기억이 뒤섞여 버려 지금 난 온전한 <color=#ffd34c>맥크레디</color>라고는 할 수 없지만."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "まあ、この子の人格と私の記憶が混ざりあったせいで、今の私は完全な<color=#ffd34c>マクレディー</color>とは言えないけど。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Well, I can't be considered the complete <color=#ffd34c>MacCready</color> because her personality and my memories have been mixed together."
L33_1.m_Talk_ENG = L34_1
L34_1 = "雖說這個孩子的人格和我的記憶混雜在一起，所以不能說現在的我是完整的<color=#ffd34c>麥克蕾蒂</color>。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "虽说这个孩子的人格和我的记忆混杂在一起，所以不能说现在的我是完整的<color=#ffd34c>麦克雷迪</color>。"
